#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    long long minMergeCost(vector<vector<int>>& lists) {
        int n = lists.size();
        int N = 1 << n;
        vector<int> len(N, 0);
        vector<int> med(N, 0);

        // Step 1: for every subset, the merged length and the left-middle median.
        for (int mask = 0; mask < N; ++mask) {
            vector<int> all;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) {
                    all.insert(all.end(), lists[i].begin(), lists[i].end());
                }
            }
            len[mask] = all.size();
            if (!all.empty()) {
                sort(all.begin(), all.end());
                med[mask] = all[(all.size() - 1) / 2];
            }
        }

        // Step 2: dp[mask] = min cost to merge the subset into one list; single list = 0.
        const long long INF = (1LL << 60);
        vector<long long> dp(N, INF);

        for (int i = 0; i < n; ++i) {
            dp[1 << i] = 0;
        }

        for (int mask = 1; mask < N; ++mask) {
            if ((mask & (mask - 1)) == 0) continue;

            // Step 3: every split into (A, B); A < B visits each unordered split once.
            for (int A = (mask - 1) & mask; A > 0; A = (A - 1) & mask) {
                int B = mask ^ A;
                if (A > B) continue;

                long long cost = dp[A] + dp[B] + len[A] + len[B] + abs((long long)med[A] - (long long)med[B]);
                if (cost < dp[mask]) {
                    dp[mask] = cost;
                }
            }
        }

        return dp[N - 1];
    }
};

