var minMergeCost = function(lists) {
    const n = lists.length;
    const totalMasks = 1 << n;
    const bitPos = new Array(totalMasks);
    for (let i = 0; i < n; i++) {
        bitPos[1 << i] = i;
    }

    const len = new Array(totalMasks).fill(0);
    const median = new Array(totalMasks).fill(0);
    const sorted = new Array(totalMasks);

    // Step 1: merged content of every subset, built by adding one list to the
    // subset without its lowest bit (already computed, since prev < mask).
    for (let mask = 1; mask < totalMasks; mask++) {
        const lsb = mask & -mask;
        const i = bitPos[lsb];
        const prev = mask ^ lsb;

        if (prev === 0) {
            sorted[mask] = lists[i].slice();
        } else {
            const a = sorted[prev];
            const b = lists[i];
            const merged = [];
            let p = 0, q = 0;
            while (p < a.length && q < b.length) {
                if (a[p] <= b[q]) {
                    merged.push(a[p++]);
                } else {
                    merged.push(b[q++]);
                }
            }
            while (p < a.length) merged.push(a[p++]);
            while (q < b.length) merged.push(b[q++]);
            sorted[mask] = merged;
        }

        len[mask] = sorted[mask].length;
        const mid = Math.floor((len[mask] - 1) / 2);   // left-middle median
        median[mask] = sorted[mask][mid];
    }

    // Step 2: dp[mask] = min cost to merge the subset into one list; single list = 0.
    const dp = new Array(totalMasks).fill(Infinity);
    for (let i = 0; i < n; i++) {
        dp[1 << i] = 0;
    }

    for (let mask = 1; mask < totalMasks; mask++) {
        if ((mask & (mask - 1)) === 0) continue;

        // Step 3: every split into (sub, other); sub < other visits each unordered split once.
        for (let sub = (mask - 1) & mask; sub > 0; sub = (sub - 1) & mask) {
            const other = mask ^ sub;
            if (sub < other) {
                const cost = len[sub] + len[other] + Math.abs(median[sub] - median[other]);
                const newCost = dp[sub] + dp[other] + cost;
                if (newCost < dp[mask]) {
                    dp[mask] = newCost;
                }
            }
        }
    }

    return dp[totalMasks - 1];
};

