import "math/bits"

func minMergeCost(lists [][]int) int64 {
    n := len(lists)
    size := 1 << n

    // merged[mask] holds the sorted union of lists selected by mask
    merged := make([][]int, size)
    merged[0] = []int{}

    // length[mask] and median[mask] are needed for the merge cost
    length := make([]int, size)
    median := make([]int, size)

    // Step 1: union, length and median for every non-empty mask, built by adding
    // one list to the mask without its lowest bit (already computed, since prev < mask)
    for mask := 1; mask < size; mask++ {
        low := mask & -mask                // lowest set bit
        i := bits.TrailingZeros(uint(low)) // index of that list
        prev := mask ^ low                 // mask without that list
        merged[mask] = mergeSorted(merged[prev], lists[i])
        l := len(merged[mask])
        length[mask] = l
        median[mask] = merged[mask][(l-1)/2] // left-middle element
    }

    const INF int64 = 1<<60 - 1
    dp := make([]int64, size)
    dp[0] = 0

    // Step 2: dp[mask] = min total cost to merge exactly the lists in mask
    for mask := 1; mask < size; mask++ {
        // A mask with a single original list needs no merges
        if mask&(mask-1) == 0 {
            dp[mask] = 0
            continue
        }
        best := INF
        // Step 3: every proper non-empty sub-mask (each unordered split is seen twice; harmless)
        for sub := (mask - 1) & mask; sub > 0; sub = (sub - 1) & mask {
            other := mask ^ sub
            cost := int64(length[sub]) + int64(length[other]) + absDiff(median[sub], median[other])
            total := dp[sub] + dp[other] + cost
            if total < best {
                best = total
            }
        }
        dp[mask] = best
    }
    return dp[size-1]
}

// merge two sorted slices into a new sorted slice
func mergeSorted(a, b []int) []int {
    res := make([]int, len(a)+len(b))
    i, j, k := 0, 0, 0
    for i < len(a) && j < len(b) {
        if a[i] <= b[j] {
            res[k] = a[i]
            i++
        } else {
            res[k] = b[j]
            j++
        }
        k++
    }
    for i < len(a) {
        res[k] = a[i]
        i++
        k++
    }
    for j < len(b) {
        res[k] = b[j]
        j++
        k++
    }
    return res
}

// absolute difference of two ints, returned as int64
func absDiff(a, b int) int64 {
    diff := int64(a - b)
    if diff < 0 {
        diff = -diff
    }
    return diff
}
